function adminRead(key,fallback){try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback))}catch{return fallback}}
function adminWrite(key,value){localStorage.setItem(key,JSON.stringify(value))}
function fillBusinessSettings(){const b=siteData.business||{};[['businessNameEdit','name'],['businessPhoneEdit','phone'],['businessEmailEdit','email'],['businessAreaEdit','area']].forEach(([id,key])=>{const el=$('#'+id);if(el)el.value=b[key]||''});const d=$('#businessDescriptionEdit');if(d)d.value=b.description||''}
function renderProductManager(){const root=$('#productManager');if(!root)return;root.innerHTML=products.map((p,i)=>`<div class="managed-product" data-product-index="${i}"><div><b>${p.name}</b><small>${p.category} · ${p.finish||''}</small></div><label>Rate ₹/sq.ft.<input class="managed-rate" type="number" min="0" value="${Number(p.price)||0}"></label><label class="upload-label">Photo<input class="managed-image" type="file" accept="image/*"></label><button class="gold-btn managed-save" type="button">Save</button></div>`).join('');root.querySelectorAll('.managed-save').forEach(btn=>btn.addEventListener('click',()=>{const row=btn.closest('.managed-product'),i=Number(row.dataset.productIndex),rate=Number(row.querySelector('.managed-rate').value);if(!Number.isFinite(rate)||rate<0)return toast('Enter a valid rate');products[i].price=rate;adminWrite('customProducts',products);renderProducts();renderMaterials();calc();toast('Product rate saved') }));root.querySelectorAll('.managed-image').forEach(input=>input.addEventListener('change',async()=>{const file=input.files?.[0],row=input.closest('.managed-product'),i=Number(row.dataset.productIndex);if(!file)return;products[i].image=await adminImageData(file);adminWrite('customProducts',products);renderProducts();toast('Product photo saved')}))}
function adminImageData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}
function bindAdminControls(){fillBusinessSettings();renderProductManager();const save=$('#saveBusinessSettings');if(save&&!save.dataset.bound){save.dataset.bound='1';save.addEventListener('click',()=>{siteData.business=siteData.business||{};siteData.business.name=$('#businessNameEdit').value.trim();siteData.business.phone=$('#businessPhoneEdit').value.trim();siteData.business.email=$('#businessEmailEdit').value.trim();siteData.business.area=$('#businessAreaEdit').value.trim();siteData.business.description=$('#businessDescriptionEdit').value.trim();adminWrite('customBusiness',siteData.business);toast('Business details saved on this device')})}const form=$('#newProductForm');if(form&&!form.dataset.bound){form.dataset.bound='1';form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form),file=fd.get('image');const item={name:String(fd.get('name')).trim(),category:String(fd.get('category')),finish:String(fd.get('finish')).trim(),price:Number(fd.get('price')),tag:String(fd.get('tag')||'New').trim(),tone:'sand'};if(file&&file.size)item.image=await adminImageData(file);if(!item.name||!Number.isFinite(item.price)||item.price<0)return toast('Complete product details');products.push(item);adminWrite('customProducts',products);renderFilters();renderProducts();renderMaterials();renderProductManager();form.reset();toast('New product added')})}const exportBtn=$('#exportData');if(exportBtn&&!exportBtn.dataset.bound){exportBtn.dataset.bound='1';exportBtn.addEventListener('click',()=>{const payload={business:siteData.business||{},products,leads:adminRead('leads',[]),quotes:adminRead('quotes',[]),exportedAt:new Date().toISOString()};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sagar-royal-admin-data.json';a.click();URL.revokeObjectURL(url);toast('Admin data exported')})}const staffSave=$('#saveStaffUpdate');if(staffSave&&!staffSave.dataset.bound){staffSave.dataset.bound='1';const range=$('#staffProgress'),out=$('#staffProgressOut');range?.addEventListener('input',()=>{if(out)out.textContent=range.value+'% complete'});staffSave.addEventListener('click',()=>{const events=adminRead('activity',[]);events.unshift({time:new Date().toISOString(),progress:range?.value||0,note:$('#staffNote')?.value||''});adminWrite('activity',events.slice(0,30));if($('#activityCount'))$('#activityCount').textContent=events.length;toast('Site update saved')})}}
const dashboardInit=initAdmin;initAdmin=function(){if(siteData.business){const custom=localStorage.getItem('customBusiness');if(custom)try{siteData.business=JSON.parse(custom)}catch{}}const customProducts=localStorage.getItem('customProducts');if(customProducts)try{products=JSON.parse(customProducts)}catch{}dashboardInit();bindAdminControls()};
function adminCategories(){const defaults=['PVC Wall Panels','WPC Louvers','UV Marble Sheets','PVC Ceiling','Hardware'];const fromProducts=products.map(p=>p.category).filter(Boolean);const custom=adminRead('customCategories',[]);return [...new Set([...defaults,...fromProducts,...custom])].sort((a,b)=>a.localeCompare(b))}
function renderCategoryControls(){const section=$('#adminProducts');if(!section)return;let box=$('#categoryManager');if(!box){box=document.createElement('div');box.id='categoryManager';box.className='category-manager';const heading=section.querySelector('h3');heading?.insertAdjacentElement('afterend',box)}const categories=adminCategories();box.innerHTML=`<div class="category-manager-head"><div><b>Catalog categories</b><small>Add your own finish or material category for future products.</small></div><form id="categoryForm" class="category-form"><input name="category" required maxlength="60" placeholder="e.g. Acoustic Panels"><button class="gold-btn" type="submit">Add category +</button></form></div><div class="category-chips">${categories.map(c=>`<span class="category-chip">${c}${adminRead('customCategories',[]).includes(c)?`<button type="button" data-remove-category="${c.replace(/"/g,'&quot;')}">×</button>`:''}</span>`).join('')}</div>`;const form=$('#categoryForm');form?.addEventListener('submit',e=>{e.preventDefault();const input=form.elements.category,value=input.value.trim();if(!value)return;const custom=adminRead('customCategories',[]);if([...adminCategories(),...custom].some(c=>c.toLowerCase()===value.toLowerCase()))return toast('Category already exists');custom.push(value);adminWrite('customCategories',[...new Set(custom)]);refreshCategorySelect();renderCategoryControls();toast('Category added to your catalog')});box.querySelectorAll('[data-remove-category]').forEach(btn=>btn.addEventListener('click',()=>{const value=btn.dataset.removeCategory;adminWrite('customCategories',adminRead('customCategories',[]).filter(c=>c!==value));refreshCategorySelect();renderCategoryControls();toast('Custom category removed')}))}
function refreshCategorySelect(){const select=$('#newProductForm select[name="category"]');if(!select)return;const current=select.value;select.innerHTML='';adminCategories().forEach(category=>{const option=document.createElement('option');option.value=category;option.textContent=category;select.appendChild(option)});if(adminCategories().includes(current))select.value=current}
const previousBindAdminControls=bindAdminControls;bindAdminControls=function(){previousBindAdminControls();refreshCategorySelect();renderCategoryControls()};
