function ensureBusinessFieldManager(){const section=document.querySelector('#adminBusiness .settings-grid');if(!section||document.querySelector('#customBusinessFields'))return;const box=document.createElement('div');box.id='customBusinessFields';box.className='custom-fields-manager';box.innerHTML=`<h4>Additional business details</h4><small>Add any extra information without changing the website code.</small><form class="custom-field-form" id="customFieldForm"><input name="label" maxlength="40" required placeholder="Label e.g. GST number"><input name="value" maxlength="120" required placeholder="Value e.g. 19ABCDE1234F1Z5"><button type="submit">Add field +</button></form><div id="customFieldList"></div>`;section.insertAdjacentElement('afterend',box);renderBusinessFields();box.querySelector('#customFieldForm').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),label=String(fd.get('label')).trim(),value=String(fd.get('value')).trim(),fields=readLocal('customBusinessFields',[]);if(fields.some(x=>x.label.toLowerCase()===label.toLowerCase()))return toast('This field already exists');fields.push({id:Date.now().toString(36),label,value});writeLocal('customBusinessFields',fields);e.currentTarget.reset();renderBusinessFields();applyPublicBusinessFields();toast('Additional business field added')})}
