function applyPublicBusinessFields(){const contact=document.querySelector('.hero-contact');if(!contact)return;let extra=contact.querySelector('.business-extra-fields');if(!extra){extra=document.createElement('div');extra.className='business-extra-fields';contact.appendChild(extra)}extra.innerHTML=readLocal('customBusinessFields',[]).map(f=>`<span><b>${escHub(f.label)}:</b> ${escHub(f.value)}</span>`).join('');if(!extra.innerHTML)extra.remove()}
function ensureCustomerHub(){if(document.querySelector('#customerHubFloat'))return;const button=document.createElement('button');button.id='customerHubFloat';button.className='customer-hub-float';button.type='button';button.title='Open all website menus';button.setAttribute('aria-label','Open customer menu');button.textContent='☰';const panel=document.createElement('div');panel.id='customerHubPanel';panel.className='customer-hub-panel';panel.hidden=true;panel.innerHTML=`<button class="customer-hub-close" id="customerHubClose" type="button">×</button><h3>Customer Control Hub</h3><small>Open every website service from one place.</small><div class="customer-hub-grid"><a href="#collection">Materials</a><a href="#calculator">Cost Calculator</a><a href="#studio">Room Studio</a><a href="#tracker">Project Tracker</a><a href="#answers">Smart FAQ</a><a href="#measurement">Free Measurement</a><a href="#stories">Client Stories</a><a href="#lookbook">2026 Lookbook</a><a href="https://wa.me/916294193478" target="_blank">WhatsApp</a><button id="customerHubAdmin" type="button">Owner / Admin</button></div>`;document.body.append(button,panel);button.addEventListener('click',()=>panel.hidden=!panel.hidden);panel.querySelector('#customerHubClose').addEventListener('click',()=>panel.hidden=true);panel.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>panel.hidden=true));panel.querySelector('#customerHubAdmin').addEventListener('click',()=>{panel.hidden=true;document.querySelector('#ownerNav')?.click()})}
