(()=>{
const defaults={visible:true,kicker:'UPI PAYMENT',title:'Scan to pay ₹499',payee:'SOUBIK MAITI · 7501709854@postbank',instructions:'After payment, send the screenshot on WhatsApp for confirmation.',note:'Payment is made by scanning the supplied UPI QR. The demo stores the booking locally.',image:'assets/sagar-royal-upi-qr.png',customImage:false};
function read(){try{return {...defaults,...JSON.parse(localStorage.getItem('qrSettings')||'{}')}}catch{return {...defaults}}}
function write(value){localStorage.setItem('qrSettings',JSON.stringify(value))}
function setText(id,value){const e=document.querySelector('#'+id);if(e)e.textContent=value}
function apply(){const q=read();const card=document.querySelector('#publicQrCard');if(card)card.hidden=!q.visible;setText('publicQrKicker',q.kicker);setText('publicQrTitle',q.title);setText('publicQrPayee',q.payee);setText('publicQrInstructions',q.instructions);setText('publicQrNote',q.note);['publicQrImage','adminQrPreviewImage'].forEach(id=>{const img=document.querySelector('#'+id);if(img){img.src=q.image;img.alt=q.title+' QR code'}});const status=document.querySelector('#adminQrStatus');if(status)status.textContent=q.customImage?'Uploaded QR image is active.':'Default QR image is active.'}
function fill(){const q=read();const map={qrKickerEdit:'kicker',qrTitleEdit:'title',qrPayeeEdit:'payee',qrInstructionsEdit:'instructions',qrNoteEdit:'note'};Object.entries(map).forEach(([id,key])=>{const e=document.querySelector('#'+id);if(e)e.value=q[key]});const toggle=document.querySelector('#qrVisibilityToggle');if(toggle)toggle.checked=q.visible;apply()}
function readFile(file){return new Promise((resolve,reject)=>{if(!file)return resolve(null);const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=reject;r.readAsDataURL(file)})}
function bind(){fill();const upload=document.querySelector('#qrImageUpload'),preview=document.querySelector('#adminQrPreviewImage');if(upload&&!upload.dataset.qrPreviewBound){upload.dataset.qrPreviewBound='1';upload.addEventListener('change',()=>{const file=upload.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>{if(preview)preview.src=String(r.result)};r.readAsDataURL(file)})}const save=document.querySelector('#saveQrSettings');if(save&&!save.dataset.qrBound){save.dataset.qrBound='1';save.addEventListener('click',async()=>{const q=read();q.visible=!!document.querySelector('#qrVisibilityToggle')?.checked;q.kicker=document.querySelector('#qrKickerEdit')?.value.trim()||defaults.kicker;q.title=document.querySelector('#qrTitleEdit')?.value.trim()||defaults.title;q.payee=document.querySelector('#qrPayeeEdit')?.value.trim()||defaults.payee;q.instructions=document.querySelector('#qrInstructionsEdit')?.value.trim()||defaults.instructions;q.note=document.querySelector('#qrNoteEdit')?.value.trim()||defaults.note;const file=upload?.files?.[0];if(file){q.image=await readFile(file);q.customImage=true}write(q);apply();if(typeof window.toast==='function')window.toast('QR settings saved on this device')})}const remove=document.querySelector('#removeQrImage');if(remove&&!remove.dataset.qrRemoveBound){remove.dataset.qrRemoveBound='1';remove.addEventListener('click',()=>{const q=read();q.image=defaults.image;q.customImage=false;write(q);if(upload)upload.value='';apply();if(typeof window.toast==='function')window.toast('Uploaded QR removed; default QR restored')})}}
function boot(){apply();bind();setTimeout(bind,350);setTimeout(bind,1000)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.sagarRoyalQr={read,apply};
})();
(()=>{
const sections=[
{id:'hero',label:'Hero / Sagar Royal Living & Interiors',selector:'.hero'},
{id:'ticker',label:'Material ticker strip',selector:'.ticker'},
{id:'quickAccess',label:'Quick Access shortcuts',selector:'.shortcut-dashboard'},
{id:'collection',label:'Material Collection',selector:'#collection'},
{id:'calculator',label:'Cost Calculator',selector:'#calculator'},
{id:'studio',label:'Interactive Room Studio',selector:'#studio'},
{id:'answers',label:'Smart Q&A / Knowledge Desk',selector:'#answers'},
{id:'tracker',label:'Project Tracker',selector:'#tracker'},
{id:'stories',label:'Client Stories',selector:'#stories'},
{id:'measurement',label:'Free Measurement + QR Payment',selector:'#measurement'},
{id:'lookbook',label:'2026 Lookbook / Download PDF',selector:'#lookbook'}
];
const defaults=Object.fromEntries(sections.map(x=>[x.id,true]));
function read(){try{return {...defaults,...JSON.parse(localStorage.getItem('sectionVisibility')||'{}')}}catch{return {...defaults}}}
function write(v){localStorage.setItem('sectionVisibility',JSON.stringify(v))}
function apply(values=read()){sections.forEach(item=>{const el=document.querySelector(item.selector);if(el)el.hidden=values[item.id]===false})}
function managerMarkup(){return `<section id="sectionVisibilityManager" class="section-visibility-manager"><h3>Website section visibility</h3><p class="modal-copy">Hide or unhide public website segments without changing their content.</p><div class="visibility-grid">${sections.map(item=>`<label class="visibility-item"><input type="checkbox" data-section-visibility="${item.id}"><span>${item.label}</span><b data-visibility-status="${item.id}">Visible</b></label>`).join('')}</div><div class="visibility-actions"><button class="gold-btn" id="saveSectionVisibility" type="button">Save visibility settings</button><button class="ghost-btn" id="showAllSections" type="button">Show all sections</button></div></section>`}
function updateStatus(root){root.querySelectorAll('[data-section-visibility]').forEach(input=>{const status=root.querySelector(`[data-visibility-status="${input.dataset.sectionVisibility}"]`);if(status)status.textContent=input.checked?'Visible':'Hidden'})}
function fill(root){const values=read();root.querySelectorAll('[data-section-visibility]').forEach(input=>{input.checked=values[input.dataset.sectionVisibility]!==false});updateStatus(root)}
function bind(){const main=document.querySelector('#adminView .admin-main');if(!main)return;let root=document.querySelector('#sectionVisibilityManager');if(!root){main.insertAdjacentHTML('afterbegin',managerMarkup());root=document.querySelector('#sectionVisibilityManager')}fill(root);root.querySelectorAll('[data-section-visibility]').forEach(input=>{if(input.dataset.bound)return;input.dataset.bound='1';input.addEventListener('change',()=>{updateStatus(root);const draft=read();draft[input.dataset.sectionVisibility]=input.checked;apply(draft)})});const save=root.querySelector('#saveSectionVisibility');if(save&&!save.dataset.bound){save.dataset.bound='1';save.addEventListener('click',()=>{const values={};root.querySelectorAll('[data-section-visibility]').forEach(input=>values[input.dataset.sectionVisibility]=input.checked);write(values);apply(values);if(typeof window.toast==='function')window.toast('Website section visibility saved')})}const all=root.querySelector('#showAllSections');if(all&&!all.dataset.bound){all.dataset.bound='1';all.addEventListener('click',()=>{const values={...defaults};write(values);fill(root);apply(values);if(typeof window.toast==='function')window.toast('All website sections are visible')})}}
function boot(){apply();bind();setTimeout(bind,400);setTimeout(bind,1100)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.sagarRoyalSectionVisibility={sections,read,write,apply};
})();
(()=>{
const fallbackCategories=['PVC Wall Panels','WPC Louvers','UV Marble Sheets','PVC Ceiling','Hardware'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localRead=(key,def)=>{try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(def))}catch{return def}};
function categories(){const custom=localRead('customCategories',[]);const values=[...fallbackCategories,...(Array.isArray(custom)?custom:[])];return [...new Set(values.concat((products||[]).map(p=>p.category).filter(Boolean)))];}
function imageData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)})}
function renderFullProductManager(){const root=document.querySelector('#productManager');if(!root)return;const list=Array.isArray(products)?products:[];root.innerHTML=list.map((p,i)=>{const options=categories().map(c=>`<option value="${esc(c)}" ${c===p.category?'selected':''}>${esc(c)}</option>`).join('');const src=p.image||'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent('<svg xmlns=\"http://www.w3.org/2000/svg\" width=240 height=180><rect width=240 height=180 fill=\"#0D2F24\"/><text x=120 y=96 text-anchor=\"middle\" fill=\"#E6C875\" font-size=16>Product photo</text></svg>');return `<article class="managed-product full-product-editor" data-product-index="${i}"><div class="product-editor-head"><img class="managed-product-preview" src="${esc(src)}" alt="${esc(p.name||'Product')} preview"><div><b>Product ${i+1}</b><small>Edit every product field, replace its photo or delete it.</small></div><button type="button" class="danger-btn managed-delete">Delete</button></div><div class="product-editor-grid"><label>Product name<input class="managed-name" value="${esc(p.name)}"></label><label>Category<select class="managed-category">${options}</select></label><label>Finish / description<input class="managed-finish" value="${esc(p.finish)}"></label><label>Rate ₹/sq.ft.<input class="managed-rate" type="number" min="0" value="${Number(p.price)||0}"></label><label>Badge / tag<input class="managed-tag" value="${esc(p.tag||'New')}"></label><label class="upload-label">Replace product photo<input class="managed-image" type="file" accept="image/*"></label></div><div class="product-editor-actions"><button type="button" class="gold-btn managed-save">Save all product details</button></div></article>`}).join('')||'<p class="empty-product-state">No products in the catalog yet.</p>';
root.querySelectorAll('.managed-image').forEach(input=>input.addEventListener('change',()=>{const file=input.files?.[0],img=input.closest('.managed-product')?.querySelector('.managed-product-preview');if(file&&img){const reader=new FileReader();reader.onload=()=>img.src=String(reader.result);reader.readAsDataURL(file)}}));
root.querySelectorAll('.managed-save').forEach(btn=>btn.addEventListener('click',async()=>{const row=btn.closest('.managed-product'),i=Number(row.dataset.productIndex),p=products[i];if(!p)return;const name=row.querySelector('.managed-name').value.trim(),finish=row.querySelector('.managed-finish').value.trim(),price=Number(row.querySelector('.managed-rate').value);if(!name||!finish||!Number.isFinite(price)||price<0)return toast('Complete product name, finish and valid rate');p.name=name;p.category=row.querySelector('.managed-category').value;p.finish=finish;p.price=price;p.tag=row.querySelector('.managed-tag').value.trim()||'New';const file=row.querySelector('.managed-image').files?.[0];if(file)p.image=await imageData(file);adminWrite('customProducts',products);renderFilters();renderProducts();renderMaterials();renderFullProductManager();toast('All product details saved')}));
root.querySelectorAll('.managed-delete').forEach(btn=>btn.addEventListener('click',()=>{const row=btn.closest('.managed-product'),i=Number(row.dataset.productIndex),p=products[i];if(!p)return;if(!window.confirm(`Delete ${p.name||'this product'} from the catalog?`))return;products.splice(i,1);adminWrite('customProducts',products);renderFilters();renderProducts();renderMaterials();renderFullProductManager();toast('Product deleted from catalog')}));}
function install(){if(typeof renderProductManager==='function')renderProductManager=renderFullProductManager;renderFullProductManager()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install);else install();
window.sagarRoyalProductManager={render:renderFullProductManager};
})();
(()=>{
const R=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d))}catch{return d}},W=(k,v)=>localStorage.setItem(k,JSON.stringify(v)),uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6),safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toastMsg=m=>typeof window.toast==='function'&&window.toast(m);
function addLog(type,data,actor=sessionStorage.username||'Admin'){const logs=R('opsLogs',[]);logs.unshift({id:uid(),type,actor,data,createdAt:new Date().toISOString(),displayTime:new Date().toLocaleString('en-IN')});W('opsLogs',logs)}
function siteForm(){const root=document.querySelector('#staffOpsPanel');if(!root||document.querySelector('#createSitePanel'))return;root.insertAdjacentHTML('afterbegin',`<div class="ops-panel missing-feature-panel" id="createSitePanel"><h3>Create New Site</h3><small>Customer details and dimensions create a unique Site ID and append a creation record.</small><div class="ops-grid"><label>Customer name<input id="newSiteCustomer" required placeholder="Customer / project name"></label><label>Address<input id="newSiteAddress" required placeholder="Full site address"></label><label>Wall / ceiling area (sq.ft.)<input id="newSiteArea" type="number" min="1" required placeholder="e.g. 450"></label><label>Assigned staff<input id="newSiteStaff" value="${safe(sessionStorage.username||'sagarstaff')}"></label></div><div class="ops-actions"><button class="ops-btn" id="createNewSite" type="button">Create Site ID</button></div><small id="newSiteResult"></small></div><div class="ops-panel missing-feature-panel" id="editRequestPanel"><h3>Request Edit / Correction</h3><small>Staff cannot alter saved project entries; submit a request for Admin approval.</small><textarea id="staffEditRequestNote" placeholder="Explain the correction needed for this site..."></textarea><div class="ops-actions"><button class="ops-btn secondary" id="submitEditRequest" type="button">Submit edit request</button></div></div>`);document.querySelector('#createNewSite').onclick=()=>{const client=document.querySelector('#newSiteCustomer').value.trim(),address=document.querySelector('#newSiteAddress').value.trim(),area=Number(document.querySelector('#newSiteArea').value),assigned=document.querySelector('#newSiteStaff').value.trim()||sessionStorage.username;if(!client||!address||!area)return toastMsg('Complete customer, address and area');const list=R('opsProjects',[]),id='SR-'+(1000+list.length+Math.floor(Math.random()*800));const project={id,client,address,area,status:'Inquiry Logged',assignedStaff:[assigned],progress:0,customerPhone:'',createdBy:sessionStorage.username,createdAt:new Date().toISOString()};list.unshift(project);W('opsProjects',list);addLog('site-created',{projectId:id,client,address,area});document.querySelector('#newSiteResult').textContent=`Created ${id} · ${client}`;document.querySelector('#newSiteCustomer').value='';document.querySelector('#newSiteAddress').value='';document.querySelector('#newSiteArea').value='';toastMsg(`New site ${id} created`);window.renderStaff?.()}}
function staffTools(){siteForm()}
function makePdf(lines){const escPdf=s=>String(s).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');const stream='BT /F1 12 Tf 50 760 Td '+lines.map((x,i)=>`(${escPdf(x)}) Tj 0 -20 Td`).join(' ')+' ET';const objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`];let out='%PDF-1.4\n',offsets=[0];objs.forEach((o,i)=>{offsets.push(out.length);out+=`${i+1} 0 obj\n${o}\nendobj\n`});const x=out.length;out+=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n`;for(let i=1;i<offsets.length;i++)out+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';out+=`trailer\n<< /Size ${objs.length+1} /Root 1 0 R >>\nstartxref\n${x}\n%%EOF`;return new Blob([out],{type:'application/pdf'})}
function downloadInvoice(project,payment){const lines=['SAGAR ROYAL LIVING & INTERIORS','PROJECT COMPLETION INVOICE','Site ID: '+project.id,'Customer: '+project.client,'Address: '+project.address,'Amount verified: Rs. '+(payment?.amount||0),'Payment method: '+(payment?.method||'Not specified'),'Status: CLOSED / ADMIN APPROVED','Generated: '+new Date().toLocaleString('en-IN')];const a=document.createElement('a');a.href=URL.createObjectURL(makePdf(lines));a.download=`${project.id}-invoice.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function waInvoice(project,payment){const msg=`Project completed and payment verified. Site ID: ${project.id}. Customer: ${project.client}. Amount: ₹${payment?.amount||0}. Invoice approved by Sagar Royal Admin.`;window.open('https://wa.me/'+(project.customerPhone||'916294193478')+'?text='+encodeURIComponent(msg),'_blank')}
function adminTools(){const root=document.querySelector('#adminView .admin-main');if(!root||document.querySelector('#missingPromptAdmin'))return;root.insertAdjacentHTML('beforeend',`<section class="ops-panel missing-feature-panel" id="missingPromptAdmin"><h3>Security, approvals &amp; completion</h3><p class="modal-copy">Prompt-required controls that were not in the existing dashboard.</p><div class="ops-panel"><h4>Staff Management &amp; password reset</h4><div id="staffResetList"></div><div class="forgot-otp"><b>Forgot Admin Password / OTP recovery</b><small>Static mode stores an OTP request locally. Connect an email/SMS provider before production use.</small><div class="ops-grid"><input id="otpRecoveryContact" placeholder="Admin email or phone"><input id="otpInput" placeholder="Enter OTP"></div><button class="ops-btn secondary" id="requestAdminOtp" type="button">Request OTP</button><button class="ops-btn" id="verifyAdminOtp" type="button">Verify OTP</button><small id="otpStatus"></small></div></div><div class="ops-panel"><h4>Project closure approval &amp; invoice</h4><div class="ops-grid"><label>Project<select id="adminCloseProject"></select></label><label>Verified amount (₹)<input id="adminCloseAmount" type="number" min="0"></label><label>Payment method<select id="adminCloseMethod"><option>UPI</option><option>Cash</option><option>Bank transfer</option></select></label></div><div class="ops-actions"><button class="ops-btn" id="verifyCloseProject" type="button">Verify payment &amp; close project</button><button class="ops-btn secondary" id="downloadCompletionInvoice" type="button">Download invoice PDF</button><button class="ops-btn secondary" id="sendCompletionWhatsApp" type="button">Send completion WhatsApp</button></div><small id="closureStatus"></small></div><div class="ops-panel"><h4>Pending staff edit requests</h4><div id="adminEditRequests"></div></div></section>`);renderAdminMissing();bindAdminMissing()}
function renderAdminMissing(){const projects=R('opsProjects',[]),select=document.querySelector('#adminCloseProject');if(select)select.innerHTML=projects.map(p=>`<option value="${safe(p.id)}">${safe(p.id)} · ${safe(p.client)} · ${safe(p.status)}</option>`).join('');const staff=document.querySelector('#staffResetList');if(staff){const rows=[{u:'sagarstaff',name:'Field Staff'},{u:'souvikmaitism',name:'Super Admin'}];staff.innerHTML=rows.map(x=>`<div class="reset-row"><b>${x.name}</b><span>${x.u}</span><button class="ops-btn secondary" data-reset-user="${x.u}" type="button">Reset Password</button><small data-reset-result="${x.u}"></small></div>`).join('');staff.querySelectorAll('[data-reset-user]').forEach(btn=>btn.onclick=()=>{const temp='SR@'+Math.random().toString(36).slice(2,8)+'9';const creds=R('temporaryCredentials',{});creds[btn.dataset.resetUser]=temp;W('temporaryCredentials',creds);const out=staff.querySelector(`[data-reset-result="${btn.dataset.resetUser}"]`);if(out)out.textContent=`Temporary password: ${temp}`;toastMsg('Temporary credential generated')})}const req=document.querySelector('#adminEditRequests'),requests=R('opsEditRequests',[]);if(req)req.innerHTML=requests.length?requests.slice(0,12).map((x,i)=>`<div class="ops-record"><b>${safe(x.projectId)} · ${safe(x.staff)}</b><small>${safe(x.note)} · ${safe(x.createdAt)}</small><button class="ops-btn secondary" data-approve-edit="${i}" type="button">Approve request</button></div>`).join(''):'<span class="ops-muted">No pending edit requests.</span>';req?.querySelectorAll('[data-approve-edit]').forEach(btn=>btn.onclick=()=>{const a=R('opsEditRequests',[]),item=a.splice(Number(btn.dataset.approveEdit),1)[0];W('opsEditRequests',a);addLog('edit-approved',item);renderAdminMissing();toastMsg('Edit request approved for controlled follow-up')})}
function bindAdminMissing(){const reset=document.querySelector('#requestAdminOtp');reset.onclick=()=>{const contact=document.querySelector('#otpRecoveryContact').value.trim();if(!contact)return toastMsg('Enter recovery email or phone');const otp=String(Math.floor(100000+Math.random()*900000));W('adminOtp',{contact,otp,expires:Date.now()+300000});document.querySelector('#otpStatus').textContent='OTP request created. Connect your email/SMS provider to deliver it securely.';toastMsg('OTP recovery request created')};document.querySelector('#verifyAdminOtp').onclick=()=>{const saved=R('adminOtp',{}),value=document.querySelector('#otpInput').value.trim();document.querySelector('#otpStatus').textContent=saved.otp&&value===saved.otp&&Date.now()<saved.expires?'OTP verified. Set a new password through your secure backend.':'OTP invalid or expired.'};document.querySelector('#verifyCloseProject').onclick=()=>{const id=document.querySelector('#adminCloseProject').value,all=R('opsProjects',[]),p=all.find(x=>x.id===id);if(!p)return;const amount=Number(document.querySelector('#adminCloseAmount').value)||0,method=document.querySelector('#adminCloseMethod').value,invoice={id:uid(),projectId:id,amount,method,createdAt:new Date().toISOString()};p.status='Closed';p.progress=100;p.paymentVerified=true;p.closedBy='souvikmaitism';p.closedAt=invoice.createdAt;W('opsProjects',all);W('opsInvoices',[invoice,...R('opsInvoices',[])]);addLog('project-closed',invoice,'souvikmaitism');document.querySelector('#closureStatus').textContent=`${id} closed after Admin payment verification.`;renderAdminMissing();window.renderAdmin?.();toastMsg('Payment verified and project closed')};document.querySelector('#downloadCompletionInvoice').onclick=()=>{const p=R('opsProjects',[]).find(x=>x.id===document.querySelector('#adminCloseProject').value),inv=R('opsInvoices',[]).find(x=>x.projectId===p?.id);if(p)downloadInvoice(p,inv)};document.querySelector('#sendCompletionWhatsApp').onclick=()=>{const p=R('opsProjects',[]).find(x=>x.id===document.querySelector('#adminCloseProject').value),inv=R('opsInvoices',[]).find(x=>x.projectId===p?.id);if(p)waInvoice(p,inv)}}
async function categoryExplore(){let cached;try{cached=JSON.parse(localStorage.getItem('customProducts')||'null')}catch{}if(!Array.isArray(cached)||!cached.length)try{cached=(await (await fetch('products.json')).json()).products}catch{}const wrap=document.querySelector('#filters');if(!wrap)return;let box=document.querySelector('#categoryExplore');if(!box){box=document.createElement('div');box.id='categoryExplore';wrap.insertAdjacentElement('afterend',box)}const cats=[...new Set((cached||[]).map(p=>p.category).filter(Boolean))];box.innerHTML=cats.map(c=>{const n=cached.filter(p=>p.category===c).length;return `<button type="button" data-explore-category="${safe(c)}">Explore ${safe(c)} (${n} variants) ↗</button>`}).join('');box.querySelectorAll('[data-explore-category]').forEach(btn=>btn.onclick=()=>{const filter=[...document.querySelectorAll('[data-filter]')].find(x=>x.dataset.filter===btn.dataset.exploreCategory);if(filter)filter.click();else{document.querySelector('#searchInput').value=btn.dataset.exploreCategory;document.querySelector('#searchInput').dispatchEvent(new Event('input'))}document.querySelector('#productGrid')?.scrollIntoView({behavior:'smooth',block:'start'})})}
function productImageFallbackFix(){document.querySelectorAll('#productManager img.managed-product-preview').forEach(img=>{if(img.src.includes('sagar-royal-upi-qr.png'))img.src='data:image/svg+xml;charset=UTF-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="240" height="180"><rect width="240" height="180" fill="#0D2F24"/><text x="120" y="96" text-anchor="middle" fill="#E6C875" font-size="16">Product photo</text></svg>')})}
function boot(){setTimeout(()=>{staffTools();adminTools();productImageFallbackFix()},400);setInterval(()=>{staffTools();adminTools();productImageFallbackFix()},5000);document.querySelector('#adminLoginBtn')?.addEventListener('click',()=>setTimeout(()=>{staffTools();adminTools()},300));document.querySelectorAll('.role-tab').forEach(x=>x.addEventListener('click',()=>setTimeout(()=>{staffTools();adminTools()},300)))}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
(()=>{
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const placeholder='data:image/svg+xml;charset=UTF-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="480" height="300"><rect width="480" height="300" fill="#0D2F24"/><text x="240" y="150" text-anchor="middle" fill="#E6C875" font-size="22">Product photo</text></svg>');
function readProducts(){try{const x=JSON.parse(localStorage.getItem('customProducts')||'null');if(Array.isArray(x)&&x.length)return x}catch{}return window.variantProducts||[]}
async function loadProducts(){const x=readProducts();if(x.length)return x;try{return (await (await fetch('products.json',{cache:'no-store'})).json()).products||[]}catch{return []}}
function ensureModal(){if(document.querySelector('#variantExplorerModal'))return;document.body.insertAdjacentHTML('beforeend',`<div class="variant-explorer-modal" id="variantExplorerModal" hidden><div class="variant-explorer-card"><button class="variant-explorer-close" id="variantExplorerClose" type="button">×</button><p class="kicker">PRODUCT COLLECTION</p><h2 id="variantExplorerTitle">Design variants</h2><p id="variantExplorerSummary" class="modal-copy"></p><div id="variantExplorerGrid" class="variant-explorer-grid"></div></div></div>`);document.querySelector('#variantExplorerClose').onclick=()=>document.querySelector('#variantExplorerModal').hidden=true;document.querySelector('#variantExplorerModal').addEventListener('click',e=>{if(e.target.id==='variantExplorerModal')e.currentTarget.hidden=true})}
async function openVariants(category,name){ensureModal();const all=await loadProducts(),variants=all.filter(p=>(p.category||'').toLowerCase()===(category||'').toLowerCase());const modal=document.querySelector('#variantExplorerModal');document.querySelector('#variantExplorerTitle').textContent=`${category} designs`;document.querySelector('#variantExplorerSummary').textContent=`${variants.length} uploaded variant${variants.length===1?'':'s'} in this collection. New Admin uploads with this category appear here automatically.`;document.querySelector('#variantExplorerGrid').innerHTML=variants.map((p,i)=>`<article class="variant-card"><img src="${esc(p.image||placeholder)}" alt="${esc(p.name)}"><div><small>VARIANT ${i+1}</small><h3>${esc(p.name)}</h3><p>${esc(p.finish||'')} </p><b>₹${Number(p.price)||0}/sq.ft.</b></div></article>`).join('')||'<p class="modal-copy">No variants uploaded for this product type yet.</p>';modal.hidden=false}
function decorate(){const grid=document.querySelector('#productGrid');if(!grid)return;grid.querySelectorAll('.product-card').forEach(card=>{if(card.querySelector('.product-explore'))return;const category=card.querySelector('.category')?.textContent.trim()||'';const name=card.querySelector('h3')?.textContent.trim()||'';const meta=card.querySelector('.product-meta');if(!meta)return;const btn=document.createElement('button');btn.type='button';btn.className='product-explore';btn.textContent='Explore variants ↗';btn.addEventListener('click',()=>openVariants(category,name));meta.appendChild(btn)})}
function boot(){ensureModal();decorate();const grid=document.querySelector('#productGrid');if(grid&&!grid.dataset.variantObserver){grid.dataset.variantObserver='1';new MutationObserver(decorate).observe(grid,{childList:true,subtree:true})}setTimeout(decorate,500)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.sagarRoyalVariants={open:openVariants,refresh:decorate};
})();
(()=>{
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d))}catch{return d}},write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=reject;r.readAsDataURL(file)})}
function managerMarkup(){return `<section class="ops-panel lookbook-admin-panel" id="adminProductLookbooks"><h3>Product Lookbook PDFs</h3><p class="modal-copy">Add a product name and upload its PDF. Customers will see each product separately in the 2026 Lookbook section.</p><form id="productLookbookForm" class="lookbook-admin-form"><label>Product name<input id="productLookbookName" list="lookbookProductNames" required placeholder="e.g. Calacatta Veil UV Marble Sheet"></label><datalist id="lookbookProductNames"></datalist><label>Lookbook PDF<input id="productLookbookFile" type="file" accept="application/pdf" required></label><button class="gold-btn" type="submit">Save product lookbook ↗</button></form><div id="productLookbookList"></div></section>`}
function renderList(){const list=read('productLookbooks',[]),root=document.querySelector('#productLookbookList');if(!root)return;root.innerHTML=list.length?list.map((x,i)=>`<div class="lookbook-admin-row"><div><b>${esc(x.productName)}</b><small>${esc(x.fileName||'Product lookbook PDF')} · Uploaded ${esc(x.uploadedAt||'')}</small></div><div><button type="button" class="ops-btn secondary" data-admin-lookbook-download="${i}">Download</button><button type="button" class="danger-btn" data-admin-lookbook-delete="${i}">Delete</button></div></div>`).join(''):'<small class="ops-muted">No product-specific lookbooks uploaded yet.</small>';root.querySelectorAll('[data-admin-lookbook-download]').forEach(btn=>btn.onclick=()=>{const x=list[Number(btn.dataset.adminLookbookDownload)];if(x){const a=document.createElement('a');a.href=x.data;a.download=x.fileName||`${x.productName}-lookbook.pdf`;a.click()}});root.querySelectorAll('[data-admin-lookbook-delete]').forEach(btn=>btn.onclick=()=>{const a=list.splice(Number(btn.dataset.adminLookbookDelete),1);write('productLookbooks',list);renderList();renderCustomerLibrary();if(typeof window.toast==='function')window.toast(`${a[0]?.productName||'Lookbook'} removed`)})}
function bindManager(){const root=document.querySelector('#adminProductLookbooks');if(!root)return;const products=read('customProducts',[]),dl=document.querySelector('#lookbookProductNames');if(dl)dl.innerHTML=[...new Set(products.map(x=>x.name).filter(Boolean))].map(x=>`<option value="${esc(x)}"></option>`).join('');renderList();const form=document.querySelector('#productLookbookForm');if(form&&!form.dataset.bound){form.dataset.bound='1';form.addEventListener('submit',async e=>{e.preventDefault();const name=document.querySelector('#productLookbookName').value.trim(),file=document.querySelector('#productLookbookFile').files?.[0];if(!name||!file||file.type!=='application/pdf')return window.toast?.('Choose a PDF and enter a product name');const list=read('productLookbooks',[]);const existing=list.findIndex(x=>x.productName.toLowerCase()===name.toLowerCase());const item={productName:name,fileName:file.name,data:await fileData(file),uploadedAt:new Date().toLocaleDateString('en-IN')};if(existing>=0)list[existing]=item;else list.unshift(item);write('productLookbooks',list);form.reset();renderList();renderCustomerLibrary();window.toast?.('Product lookbook saved for customers')})}}
function ensureAdminManager(){const main=document.querySelector('#adminView .admin-main');if(!main)return;if(!document.querySelector('#adminProductLookbooks')){const anchor=document.querySelector('#adminNewProduct')||main.lastElementChild;anchor.insertAdjacentHTML('afterend',managerMarkup())}bindManager()}
function ensureCustomerModal(){if(document.querySelector('#productLookbookModal'))return;document.body.insertAdjacentHTML('beforeend',`<div class="product-lookbook-modal" id="productLookbookModal" hidden><div class="product-lookbook-card"><button class="variant-explorer-close" id="productLookbookClose" type="button">×</button><p class="kicker">2026 PRODUCT LOOKBOOKS</p><h2>Choose your<br><em>product design.</em></h2><p class="modal-copy">Select a product to download its lookbook PDF.</p><div id="customerLookbookList" class="customer-lookbook-list"></div></div></div>`);document.querySelector('#productLookbookClose').onclick=()=>document.querySelector('#productLookbookModal').hidden=true;document.querySelector('#productLookbookModal').addEventListener('click',e=>{if(e.target.id==='productLookbookModal')e.currentTarget.hidden=true})}
function renderCustomerLibrary(){ensureCustomerModal();const list=read('productLookbooks',[]),root=document.querySelector('#customerLookbookList');if(!root)return;root.innerHTML=list.length?list.map((x,i)=>`<button class="customer-lookbook-item" type="button" data-customer-lookbook="${i}"><span>PDF</span><div><b>${esc(x.productName)}</b><small>Download product lookbook ↗</small></div></button>`).join(''):'<p class="modal-copy">Product lookbooks will appear here after Admin uploads them.</p>';root.querySelectorAll('[data-customer-lookbook]').forEach(btn=>btn.onclick=()=>{const x=list[Number(btn.dataset.customerLookbook)];if(x){const a=document.createElement('a');a.href=x.data;a.download=x.fileName||`${x.productName}-lookbook.pdf`;a.click()}})}
function bindCustomerButton(){const old=document.querySelector('#lookbookOpen');if(!old||old.dataset.productLookbookBound)return;const btn=old.cloneNode(true);btn.dataset.productLookbookBound='1';old.replaceWith(btn);btn.addEventListener('click',e=>{e.preventDefault();ensureCustomerModal();renderCustomerLibrary();document.querySelector('#productLookbookModal').hidden=false})}
function boot(){ensureCustomerModal();bindCustomerButton();setTimeout(()=>{ensureAdminManager();bindCustomerButton()},500);setInterval(()=>{ensureAdminManager();bindCustomerButton()},5000);renderCustomerLibrary()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.sagarRoyalLookbooks={renderCustomerLibrary,renderList};
})();
(()=>{
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d))}catch{return d}},write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={year:'2026',title:'Design ideas, made practical.',description:'Get the latest PVC, WPC, ceiling and modular kitchen lookbook in your inbox.'};
function settings(){return {...defaults,...read('lookbookSettings',{})}}
function applyPublic(){const s=settings(),section=document.querySelector('#lookbook');if(section){const k=section.querySelector('.kicker');if(k)k.textContent=`FREE ${s.year} LOOKBOOK`;const h=section.querySelector('h2');if(h){const comma=s.title.indexOf(',');h.innerHTML=comma>=0?`${esc(s.title.slice(0,comma+1))}<br><em>${esc(s.title.slice(comma+1).trim())}</em>`:esc(s.title)}const p=section.querySelector('p:not(.kicker)');if(p)p.textContent=s.description;const btn=section.querySelector('#lookbookOpen');if(btn)btn.textContent=`Download ${s.year} lookbook PDF ↗`}const modal=document.querySelector('#productLookbookModal');if(modal){const k=modal.querySelector('.kicker');if(k)k.textContent=`${s.year} PRODUCT LOOKBOOKS`}}
function lookbookSettingsMarkup(){return `<div class="lookbook-settings-box" id="lookbookDisplaySettings"><h4>Lookbook display settings</h4><small>Edit the year and public Lookbook wording without changing code.</small><div class="ops-grid"><label>Lookbook year<input id="lookbookYearEdit" inputmode="numeric" maxlength="4"></label><label>Section title<input id="lookbookTitleEdit" maxlength="90"></label></div><label>Description<textarea id="lookbookDescriptionEdit" maxlength="220"></textarea></label><button class="gold-btn" id="saveLookbookDisplay" type="button">Save Lookbook display</button><small id="lookbookDisplayStatus"></small></div>`}
function bindSettings(){const root=document.querySelector('#lookbookDisplaySettings');if(!root)return;const s=settings();const y=root.querySelector('#lookbookYearEdit'),t=root.querySelector('#lookbookTitleEdit'),d=root.querySelector('#lookbookDescriptionEdit');if(y&&!y.dataset.filled){y.value=s.year;t.value=s.title;d.value=s.description;y.dataset.filled='1'}const btn=root.querySelector('#saveLookbookDisplay');if(btn&&!btn.dataset.bound){btn.dataset.bound='1';btn.onclick=()=>{const value={year:y.value.trim()||defaults.year,title:t.value.trim()||defaults.title,description:d.value.trim()||defaults.description};write('lookbookSettings',value);applyPublic();root.querySelector('#lookbookDisplayStatus').textContent=`Saved: ${value.year} Lookbook is now visible on the website.`;window.toast?.('Lookbook display updated')}}}
function ensureSettings(){const manager=document.querySelector('#adminProductLookbooks');if(!manager)return;if(!document.querySelector('#lookbookDisplaySettings'))manager.insertAdjacentHTML('afterbegin',lookbookSettingsMarkup());bindSettings()}
const links=[['adminBusiness','Business Details'],['adminProducts','Products & Photos'],['adminNewProduct','Add New Product'],['adminProductLookbooks','Product Lookbook PDFs'],['adminCRM','Lead CRM'],['adminPayment','Payment QR'],['sectionVisibilityManager','Section Visibility'],['missingPromptAdmin','Security & Approvals'],['adminStaffShortcut','Staff Operations'],['adminExport','Export Data']];
function ensureMenu(){const dash=document.querySelector('#adminDashboard'),bar=dash?.querySelector('.admin-rolebar');if(!dash||!bar)return;let toggle=document.querySelector('#adminFeatureMenuToggle');if(!toggle){toggle=document.createElement('button');toggle.id='adminFeatureMenuToggle';toggle.type='button';toggle.className='admin-feature-menu-toggle';toggle.setAttribute('aria-label','Open Admin feature menu');toggle.textContent='⋯';bar.appendChild(toggle);const panel=document.createElement('div');panel.id='adminFeatureMenu';panel.className='admin-feature-menu';panel.hidden=true;panel.innerHTML=`<div class="admin-feature-menu-head"><b>Admin Features</b><button type="button" id="adminFeatureMenuClose">×</button></div><div id="adminFeatureMenuLinks"></div>`;dash.appendChild(panel);toggle.onclick=()=>{panel.hidden=!panel.hidden;renderMenu()};panel.querySelector('#adminFeatureMenuClose').onclick=()=>panel.hidden=true;document.addEventListener('click',e=>{if(!panel.hidden&&!panel.contains(e.target)&&e.target!==toggle)panel.hidden=true})}renderMenu()}
function renderMenu(){const root=document.querySelector('#adminFeatureMenuLinks');if(!root)return;root.innerHTML=links.map(([id,label])=>`<button type="button" data-admin-feature-link="${id}">${label}<span>↗</span></button>`).join('');root.querySelectorAll('[data-admin-feature-link]').forEach(btn=>btn.onclick=()=>{const target=document.querySelector('#'+btn.dataset.adminFeatureLink);if(target){target.hidden=false;target.scrollIntoView({behavior:'smooth',block:'start'})}const panel=document.querySelector('#adminFeatureMenu');if(panel)panel.hidden=true})}
function boot(){applyPublic();setTimeout(()=>{ensureSettings();ensureMenu()},500);setInterval(()=>{applyPublic();ensureSettings();ensureMenu()},1500)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.sagarRoyalAdminMenu={applyPublic,ensureMenu};
})();
