function bindStaffPanel(){const root=document.querySelector('#adminStaffAccounts');if(!root)return;renderStaffAccounts();const form=root.querySelector('#createStaffAccountForm');if(form&&form.dataset.bound)return;if(form){form.dataset.bound='1';form.onsubmit=e=>{e.preventDefault();const name=root.querySelector('#newStaffName').value.trim(),username=root.querySelector('#newStaffUsername').value.trim(),password=root.querySelector('#newStaffPassword').value;if(!name||!username||password.length<6)return toast('Enter a name, Staff ID and a password of at least 6 characters');if(username.toLowerCase()==='sagarstaff'||username.toLowerCase()==='souvikmaitism')return toast('This Staff ID is reserved');const list=staffUsers();if(list.some(x=>x.username.toLowerCase()===username.toLowerCase()))return toast('That Staff ID already exists');list.push({name,username,password,createdAt:new Date().toLocaleString('en-IN')});write('customStaffUsers',list);form.reset();renderStaffAccounts();toast(`Staff ID ${username} created successfully`)}}}
function ensureStaffPanel(){const main=document.querySelector('#adminView .admin-main');if(!main||sessionStorage.role!=='admin')return;if(!document.querySelector('#adminStaffAccounts')){const anchor=document.querySelector('#adminStaffShortcut')||main.lastElementChild;anchor.insertAdjacentHTML('afterend',staffPanel())}bindStaffPanel()}
function addLogout(){const bar=document.querySelector('#adminDashboard .admin-rolebar');if(!bar||document.querySelector('#dashboardLogout'))return;const b=document.createElement('button');b.id='dashboardLogout';b.type='button';b.className='dashboard-logout';b.textContent='Logout';b.onclick=()=>{sessionStorage.removeItem('owner');sessionStorage.removeItem('role');const dash=document.querySelector('#adminDashboard'),login=document.querySelector('#adminLogin'),modal=document.querySelector('#adminModal');if(dash)dash.hidden=true;if(login)login.hidden=false;if(modal)modal.hidden=false;toast('You have been logged out')};bar.appendChild(b)}
function customLogin(){const role=document.querySelector('#loginRole')?.value,u=document.querySelector('#adminUsername')?.value.trim(),p=document.querySelector('#adminPassword')?.value;let ok=false;if(role==='admin')ok=u==='souvikmaitism'&&p==='31102006ms@';if(role==='staff')ok=(u==='sagarstaff'&&p==='Staff@31102006')||staffUsers().some(x=>x.username===u&&x.password===p);if(!ok){toast('Incorrect credentials');return false}sessionStorage.owner='yes';sessionStorage.role=role;sessionStorage.staffUsername=role==='staff'?u:'';if(typeof window.initAdmin==='function')window.initAdmin();else{document.querySelector('#adminLogin').hidden=true;document.querySelector('#adminDashboard').hidden=false}setTimeout(()=>{addLogout();ensureStaffPanel()},200);return true}
