function contrast(){document.querySelectorAll('#adminDashboard label,#adminDashboard p,#adminDashboard small,#adminDashboard span,#adminDashboard h4,#adminDashboard h3,#adminDashboard .modal-copy').forEach(x=>{if(!x.closest('.admin-feature-menu'))x.classList.add('dashboard-readable')})}
function boot(){replaceLogin();if(sessionStorage.owner==='yes'){setTimeout(()=>{addLogout();ensureStaffPanel();contrast()},300)}setInterval(()=>{replaceLogin();if(sessionStorage.owner==='yes'){addLogout();ensureStaffPanel();contrast()}},1000)}
